function getAllWeddingHalls() {
  const kas = (typeof KASARAGOD_WEDDING_HALLS !== 'undefined' ? KASARAGOD_WEDDING_HALLS : []).map(h => ({ district: 'kasaragod', ...h }));
  const clt = (typeof KOZHIKODE_WEDDING_HALLS !== 'undefined' ? KOZHIKODE_WEDDING_HALLS : []).map(h => ({ district: 'kozhikode', ...h }));
  const knr = (typeof KANNUR_WEDDING_HALLS !== 'undefined' ? KANNUR_WEDDING_HALLS : []).map(h => ({ district: 'kannur', ...h }));
  const mlp = (typeof MALAPPURAM_WEDDING_HALLS !== 'undefined' ? MALAPPURAM_WEDDING_HALLS : []).map(h => ({ district: 'malappuram', ...h }));
  const wyd = (typeof WAYANAD_WEDDING_HALLS !== 'undefined' ? WAYANAD_WEDDING_HALLS : []).map(h => ({ district: 'wayanad', ...h }));
  return [...kas, ...clt, ...knr, ...mlp, ...wyd];
}

// -------------------------------------------------------------
// Geo & Distance Calculation Engine (Haversine Formula)
// -------------------------------------------------------------
function calculateDistanceKm(lat1, lon1, lat2, lon2) {
  if (!lat1 || !lon1 || !lat2 || !lon2) return null;
  const R = 6371; // Earth radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
    Math.sin(dLon/2) * Math.sin(dLon/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return Math.round((R * c) * 10) / 10; // Round to 1 decimal place (e.g. 3.2 km)
}

function findNearestDistrict(userLat, userLng) {
  let nearestDistrict = null;
  let minDistance = Infinity;

  KERALA_DISTRICTS.forEach(district => {
    const dist = calculateDistanceKm(userLat, userLng, district.lat, district.lng);
    if (dist < minDistance) {
      minDistance = dist;
      nearestDistrict = {
        ...district,
        distanceKm: dist
      };
    }
  });

  return nearestDistrict;
}

function analyzeNearbyVendors(userLat, userLng, vendors) {
  // Compute distance for all vendors
  const withDistance = vendors.map(v => {
    const dist = calculateDistanceKm(userLat, userLng, v.lat, v.lng);
    return {
      ...v,
      distanceKm: dist !== null ? dist : 9999
    };
  });

  // Sort by nearest first
  withDistance.sort((a, b) => a.distanceKm - b.distanceKm);

  // Group by category to find closest in each category
  const categories = ['meat', 'vegetables', 'rentals', 'home_prep', 'logistics'];
  const nearestPerCategory = {};

  categories.forEach(cat => {
    const match = withDistance.find(v => v.category === cat);
    if (match) {
      nearestPerCategory[cat] = match;
    }
  });

  return {
    sortedVendors: withDistance,
    nearestPerCategory
  };
}

// -------------------------------------------------------------
// Wedding BOM & Budget Helpers
// -------------------------------------------------------------
function calculateWeddingBOM(menuKey, guestCount) {
  const menu = WEDDING_MENUS[menuKey];
  if (!menu) return null;

  const factor = guestCount / 100;
  let totalRawMaterialCost = 0;

  const calculatedItems = menu.bomPer100Guests.map(item => {
    const totalQty = Math.round((item.qty * factor) * 10) / 10;
    const estCost = Math.round(totalQty * item.estRate);
    totalRawMaterialCost += estCost;
    return {
      ...item,
      totalQty,
      estCost
    };
  });

  const cateringContractCost = Math.round(guestCount * menu.typicalCateringPricePerPlate);
  const selfManagedCost = totalRawMaterialCost;
  const masterCookLabour = Math.round(guestCount * 45);
  const totalDirectCost = selfManagedCost + masterCookLabour;
  const estimatedSavings = cateringContractCost - totalDirectCost;

  return {
    menu,
    guestCount,
    calculatedItems,
    totalRawMaterialCost,
    masterCookLabour,
    totalDirectCost,
    cateringContractCost,
    estimatedSavings: Math.max(0, estimatedSavings)
  };
}

function calculateBudgetOptimization(targetBudget, guestCount) {
  const perPersonAvailable = Math.round(targetBudget / guestCount);

  const allocation = {
    food: Math.round(targetBudget * 0.48),
    pandal: Math.round(targetBudget * 0.22),
    rentals: Math.round(targetBudget * 0.10),
    homePrep: Math.round(targetBudget * 0.12),
    logistics: Math.round(targetBudget * 0.08)
  };

  let recommendedMenu = 'malabar_chicken_biryani';
  let budgetHealth = 'Optimal';
  let advice = [];

  if (perPersonAvailable >= 600) {
    budgetHealth = 'Luxury';
    recommendedMenu = 'malabar_mutton_biryani';
    advice.push('Your budget comfortably supports Grand Mutton Biryani or a Multi-course Royal Sadya with live welcome drinks.');
    advice.push('You can opt for waterproof German Truss pandal and imported banquet furniture.');
  } else if (perPersonAvailable >= 350) {
    budgetHealth = 'Optimal';
    recommendedMenu = 'malabar_mutton_biryani';
    advice.push('Ideal budget! Procuring raw mutton and spices directly from wholesale markets will save you up to 35% compared to full caterers.');
    advice.push('Reserve ₹20,000 - ₹30,000 for house painting and yard preparation.');
  } else if (perPersonAvailable >= 220) {
    budgetHealth = 'Cost-Smart';
    recommendedMenu = 'malabar_chicken_biryani';
    advice.push('We recommend Malabar Chicken Dum Biryani or Traditional Kerala Sadya to stay perfectly within budget.');
    advice.push('Hiring a professional master cook team with self-sourced wholesale materials will give you premium taste at wholesale rates.');
  } else {
    budgetHealth = 'Tight';
    recommendedMenu = 'kerala_sadya';
    advice.push('Direct wholesale sourcing of vegetables from APMC Mandis (Chalai/Broadway/Sakthan) is essential to stay within budget.');
    advice.push('Opt for local Shamiana and hire regular plastic banquet chairs instead of cushion sofas.');
  }

  return {
    targetBudget,
    guestCount,
    perPersonAvailable,
    allocation,
    recommendedMenu: WEDDING_MENUS[recommendedMenu],
    budgetHealth,
    advice
  };
}

// -------------------------------------------------------------
// 15. Kerala Catering Labour Ratios & Benchmarks
// -------------------------------------------------------------
const CATERING_LABOUR_BENCHMARKS = {
  headChefPerPlateBiryani: 40,
  headChefPerPlateSadya: 35,
  headChefDailyMin: 4500,
  assistantCookWage: 1200,
  assistantCookRatio: 150, // 1 per 150 guests
  serverWage: 900,
  serverRatioSadya: 30, // 1 server per 30 guests (for leaf service)
  serverRatioBiryani: 45, // 1 server per 45 guests (buffet / table)
  cleanerWage: 1000,
  cleanerRatio: 120, // 1 dishwashing/cleaner per 120 guests
  teaCounterWage: 900
};

function calculateLabourCostBreakdown(menuKey, guestCount) {
  const isSadya = menuKey === 'kerala_sadya';
  const chefRatePerPlate = isSadya ? CATERING_LABOUR_BENCHMARKS.headChefPerPlateSadya : CATERING_LABOUR_BENCHMARKS.headChefPerPlateBiryani;
  const headChefFee = Math.max(CATERING_LABOUR_BENCHMARKS.headChefDailyMin, Math.round(guestCount * chefRatePerPlate));
  
  const assistantCount = Math.max(2, Math.ceil(guestCount / CATERING_LABOUR_BENCHMARKS.assistantCookRatio));
  const assistantCost = assistantCount * CATERING_LABOUR_BENCHMARKS.assistantCookWage;

  const serverRatio = isSadya ? CATERING_LABOUR_BENCHMARKS.serverRatioSadya : CATERING_LABOUR_BENCHMARKS.serverRatioBiryani;
  const serverCount = Math.max(4, Math.ceil(guestCount / serverRatio));
  const serverCost = serverCount * CATERING_LABOUR_BENCHMARKS.serverWage;

  const cleanerCount = Math.max(2, Math.ceil(guestCount / CATERING_LABOUR_BENCHMARKS.cleanerRatio));
  const cleanerCost = cleanerCount * CATERING_LABOUR_BENCHMARKS.cleanerWage;

  const teaBoysCount = guestCount >= 400 ? 2 : 1;
  const teaCost = teaBoysCount * CATERING_LABOUR_BENCHMARKS.teaCounterWage;

  const totalLabourCost = headChefFee + assistantCost + serverCost + cleanerCost + teaCost;
  const totalStaffCount = 1 + assistantCount + serverCount + cleanerCount + teaBoysCount;

  return {
    guestCount,
    isSadya,
    headChefFee,
    assistantCount,
    assistantCost,
    serverCount,
    serverCost,
    cleanerCount,
    cleanerCost,
    teaBoysCount,
    teaCost,
    totalLabourCost,
    totalStaffCount,
    avgLabourCostPerPlate: Math.round(totalLabourCost / guestCount)
  };
}

// -------------------------------------------------------------
// 16. Kerala Auditorium & Dining Batch (പന്തി) Capacity Formulas
// -------------------------------------------------------------
function calculateAuditoriumCapacity(guestCount) {
  const diningSeats = Math.max(80, Math.round(guestCount * 0.25));
  const batchesCount = Math.ceil(guestCount / diningSeats);
  const diningTimeMins = (batchesCount * 25) + ((batchesCount - 1) * 8); // 25 min batch + 8 min turnover cleaning
  
  const mainHallCapacity = Math.round(guestCount * 0.65);
  const auditoriumAreaSqft = Math.round(guestCount * 7.5);
  const carParkingSlots = Math.round(guestCount * 0.12);
  const twoWheelerSlots = Math.round(guestCount * 0.15);
  const handwashTaps = Math.max(6, Math.round(diningSeats / 18));

  return {
    guestCount,
    diningSeats,
    batchesCount,
    diningTimeMins,
    diningTimeHours: (diningTimeMins / 60).toFixed(1),
    mainHallCapacity,
    auditoriumAreaSqft,
    carParkingSlots,
    twoWheelerSlots,
    handwashTaps
  };
}

